48	#  define NEED_BOARDINIT 1
49	#endif
50	
51	/****************************************************************************
52	 * Public Functions
53	 ****************************************************************************/
54	
55	int main(int argc, FAR char *argv[])
56	{
57	    lv_nuttx_dsc_t info;
58	    lv_nuttx_result_t result;
59	
60	    /* 开机卡logo取证：SD syslog 重定向前此行走console（无串口则丢），
61	     * 之后进 app.log。日志停在 entry 后 = 显示/资源初始化卡死。 */
62	    syslog(LOG_INFO, "[MAIN] watch main: entry");
63	
64	    /* 显式设置东八区时区，确保本进程的 mktime()/localtime() 按 CST-8 处理。
65	     * 板级 bringup 虽设置了 TZ，但本应用进程未必继承；若不设置，
66	     * 手动修改时间时 mktime() 会把本地时间当作 UTC 写入系统时钟，
67	     * localtime() 再 +8 显示，导致时间快 8 小时。
68	     */
69	#ifdef CONFIG_LIBC_LOCALTIME
70	    setenv("TZ", "CST-8", 1);
71	    tzset();
72	
73	    /* 启动时修正 CLOCK_REALTIME：RTC 存的是本地时间（broken-down），
74	     * clock_basetime 用 timegm() 把它当 UTC 读入 CLOCK_REALTIME，导致
75	     * CLOCK_REALTIME 比真正 UTC 快 tz_offset 秒。这里减去 tz_offset
76	     * 修正为真正 UTC，localtime() 再 +8 显示即正确。
77	     */
78	    {
79	        struct timeval tv;
80	        if (gettimeofday(&tv, NULL) == 0)
81	        {
82	            time_t tprobe = 0;
83	            struct tm lt_probe, gt_probe;
84	            localtime_r(&tprobe, &lt_probe);
85	            gmtime_r(&tprobe, &gt_probe);
86	            long tz_offset = (lt_probe.tm_hour - gt_probe.tm_hour) * 3600L +
87	                             (lt_probe.tm_min  - gt_probe.tm_min)  * 60L +
88	                             (lt_probe.tm_sec  - gt_probe.tm_sec);
89	            while (tz_offset > 43200)  tz_offset -= 86400;
90	            while (tz_offset < -43200) tz_offset += 86400;
91	
92	            if (tz_offset != 0)
93	            {
94	                tv.tv_sec -= tz_offset;
95	                settimeofday(&tv, NULL);
96	            }
97	        }
98	    }
99	#endif
100	
101	    if (lv_is_initialized())
102	    {
103	      LV_LOG_ERROR("LVGL already initialized! aborting.");
104	      return -1;
105	    }
106	
107	#ifdef NEED_BOARDINIT
108	    /* Perform board-specific driver initialization if not already done */
109	    boardctl(BOARDIOC_INIT, 0);
110	#endif
111	
112	    lv_init();
113	
114	    lv_nuttx_dsc_init(&info);
115	
116	#ifdef CONFIG_LV_USE_NUTTX_LCD
117	    info.fb_path = "/dev/lcd0";
118	#endif
119	
120	#ifdef CONFIG_INPUT_TOUCHSCREEN
121	    info.input_path = "/dev/input0";
122	#endif
123	
124	    lv_nuttx_init(&info, &result);
125	
126	    if (result.disp == NULL)
127	    {
128	      LV_LOG_ERROR("lv_demos initialization failure!");
129	      return 1;
130	    }
131	
132	    /* 初始化资源管理（加载开机logo和动画帧数据） */
133	    watch_resource_init();
134	    syslog(LOG_INFO, "[MAIN] display+resources ready");
135	
136	    /* WiFi开机自动初始化：在开机动画期间完成WiFi连接 */
137	    settings_wifi_auto_init();
138	
139	    /* 启动物理按键监控（BOOT长按进入设置，PWR短按返回主页） */
140	    watch_button_monitor_init();
141	    syslog(LOG_INFO, "[MAIN] wifi+button init done");
142	
143	    /* 启动开机logo → 开机动画流程 */
144	    launcher_init(lv_scr_act());
145	    syslog(LOG_INFO, "[MAIN] launcher init done");
146	
147	    /* 进入LVGL事件循环 */
148	    //printf("[MAIN] Entering LVGL event loop\n");
149	    while (1)
150	    {
151	      uint32_t idle;
152	      idle = lv_timer_handler();
153	
154	      /* Minimum sleep of 1ms */
155	      idle = idle ? idle : 1;
156	      usleep(idle * 1000);
157	    }
158	
159	    lv_nuttx_deinit(&result);
160	    lv_deinit();
161	
162	    return 0;
163	}
