32	
33	#define UI_MODE_CONFIG_FILE  "/mnt/spif/ui_mode.json"
34	#define UI_MODE_KEY          "\"ui_mode\":"
35	
36	/****************************************************************************
37	 * Private Data
38	 ****************************************************************************/
39	
40	static ui_mode_t g_current_ui_mode = UI_MODE_EXPRESSION;
41	static lv_obj_t *g_switch_overlay = NULL;
42	
43	/****************************************************************************
44	 * Private Functions
45	 ****************************************************************************/
46	
47	/**
48	 * @brief 显示模式切换遮罩（全屏黑底 + 转圈 + 提示文字）
49	 */
50	static void show_switch_overlay(lv_obj_t *parent)
51	{
52	  if (g_switch_overlay != NULL)
53	    {
54	      return;
55	    }
56	
57	  /* 全屏遮罩 */
58	  g_switch_overlay = lv_obj_create(parent);
59	  lv_obj_set_size(g_switch_overlay, LV_PCT(100), LV_PCT(100));
60	  lv_obj_set_style_bg_color(g_switch_overlay, lv_color_hex(0x000000), 0);
61	  lv_obj_set_style_bg_opa(g_switch_overlay, LV_OPA_90, 0);
62	  lv_obj_set_style_border_width(g_switch_overlay, 0, 0);
63	  lv_obj_set_style_radius(g_switch_overlay, 0, 0);
64	  lv_obj_clear_flag(g_switch_overlay, LV_OBJ_FLAG_SCROLLABLE);
65	  lv_obj_center(g_switch_overlay);
66	
67	  /* 转圈动画 */
68	  lv_obj_t *spinner = lv_spinner_create(g_switch_overlay);
69	  lv_obj_set_size(spinner, 80, 80);
70	  lv_obj_center(spinner);
71	
72	  /* 提示文字 */
73	  lv_obj_t *label = lv_label_create(g_switch_overlay);
74	  lv_label_set_text(label, "Switching...");
75	  lv_obj_set_style_text_color(label, lv_color_hex(0xFFFFFF), 0);
76	  lv_obj_set_style_text_font(label, LV_FONT_DEFAULT, 0);
77	  lv_obj_align_to(label, spinner, LV_ALIGN_OUT_BOTTOM_MID, 0, 20);
78	
79	  /* 强制刷新，确保遮罩立即显示 */
80	  lv_refr_now(NULL);
81	}
82	
83	/**
84	 * @brief 隐藏并删除模式切换遮罩
85	 */
86	static void hide_switch_overlay(void)
87	{
88	  if (g_switch_overlay != NULL)
89	    {
90	      lv_obj_del(g_switch_overlay);
91	      g_switch_overlay = NULL;
92	    }
93	}
94	
95	/****************************************************************************
96	 * Public Functions
97	 ****************************************************************************/
98	
99	/**
100	 * @brief 从持久化配置文件加载 UI 模式
101	 *
102	 * JSON 格式: {"ui_mode":0}  (0=表情, 1=手表)
103	 * 文件不存在或解析失败时返回 UI_MODE_EXPRESSION。
104	 */
105	ui_mode_t ui_mode_load(void)
106	{
107	  FILE *fp;
108	  char buf[64];
109	  int  mode_val = (int)UI_MODE_EXPRESSION;
110	
111	  fp = fopen(UI_MODE_CONFIG_FILE, "r");
112	  if (fp == NULL)
113	    {
114	      /* 文件不存在，返回默认值 */
115	      return UI_MODE_EXPRESSION;
116	    }
117	
118	  /* 读取文件内容（文件很小，一次读取即可） */
119	  if (fgets(buf, sizeof(buf), fp) != NULL)
120	    {
121	      /* 查找 "ui_mode": 键 */
122	      char *key_pos = strstr(buf, UI_MODE_KEY);
123	      if (key_pos != NULL)
124	        {
125	          /* 跳过键名，解析整数值 */
126	          key_pos += strlen(UI_MODE_KEY);
127	          mode_val = atoi(key_pos);
128	        }
129	    }
130	
131	  fclose(fp);
132	
133	  /* 确保返回值在有效范围内 */
134	  if (mode_val != (int)UI_MODE_EXPRESSION &&
135	      mode_val != (int)UI_MODE_WATCH)
136	    {
137	      mode_val = (int)UI_MODE_EXPRESSION;
138	    }
139	
140	  return (ui_mode_t)mode_val;
141	}
142	
143	/**
144	 * @brief 保存 UI 模式到持久化配置文件
145	 *
146	 * JSON 格式: {"ui_mode":0}  (0=表情, 1=手表)
147	 */
148	void ui_mode_save(ui_mode_t mode)
149	{
150	  FILE *fp;
151	
152	  fp = fopen(UI_MODE_CONFIG_FILE, "w");
153	  if (fp == NULL)
154	    {
155	      return;
156	    }
157	
158	  fprintf(fp, "{\"ui_mode\":%d}\n", (int)mode);
159	  fclose(fp);
160	}
161	
162	/**
163	 * @brief 设置当前运行时的 UI 模式（由 launcher 在开机时调用）
164	 */
165	void ui_mode_set_current(ui_mode_t mode)
166	{
167	  g_current_ui_mode = mode;
168	}
169	
170	/**
171	 * @brief 获取当前运行时的 UI 模式
172	 */
173	ui_mode_t ui_mode_get_current(void)
174	{
175	  return g_current_ui_mode;
176	}
177	
178	/**
179	 * @brief 无重启切换到指定 UI 模式
180	 *
181	 * 清理当前 UI 资源，初始化目标 UI。切换完成后写入持久化配置，
182	 * 保证下次开机仍进入该模式。
183	 *
184	 * 注意：手表模式启动时跳过了 ai_agent（launcher.c agent_autostart 仅表情模式启动），
185	 * 运行时切换到表情模式后，由 launcher_start_voice_for_expression() 补齐
186	 * ai_agent 拉起 + 唤醒词监听，否则不进 listen 状态。
187	 */
188	int ui_mode_switch_runtime(ui_mode_t target, lv_obj_t *parent)
189	{
190	  if (parent == NULL)
191	    {
192	      return -1;
193	    }
194	
195	  if (target == g_current_ui_mode)
196	    {
197	      return 0;
198	    }
199	
200	  extern int watch_switch_to_watch_app(lv_obj_t *parent);
201	  extern int watch_switch_to_expression_app(lv_obj_t *parent);
202	
203	  int ret = 0;
204	
205	  /* 显示切换遮罩，避免耗时清理/初始化期间 UI 假死 */
206	  show_switch_overlay(parent);
207	
208	  if (target == UI_MODE_WATCH)
209	    {
210	      /* 潮玩 → 手表：先停止表情模式的后台任务（语音会话 / E2E 链路 /
211	       * ai_agent），与冷启动进手表模式的行为对齐（手表模式不运行
212	       * ai_agent，见 launcher.c agent_autostart）；切回表情模式时由
213	       * launcher_start_voice_for_expression() 重新拉起 */
214	      extern void launcher_stop_voice_for_watch(void);
215	      launcher_stop_voice_for_watch();
216	
217	      /* 潮玩 → 手表 */
218	      ret = watch_switch_to_watch_app(parent);
219	    }
220	  else
221	    {
222	      /* 手表 → 潮玩 */
223	      ret = watch_switch_to_expression_app(parent);
224	    }
225	
226	  hide_switch_overlay();
227	
228	  if (ret == 0)
229	    {
230	      g_current_ui_mode = target;
231	      ui_mode_save(target);
232	
233	      /* 切到表情模式后，启动 ai_agent + 唤醒词监听
234	       * 手表模式启动时跳过了 ai_agent（见 launcher.c agent_autostart），
235	       * 运行时切换到表情需在此补齐，否则不进 listen 状态 */
236	      if (target == UI_MODE_EXPRESSION)
237	        {
238	          extern void launcher_start_voice_for_expression(void);
239	          launcher_start_voice_for_expression();
240	        }
241	    }
242	
243	  return ret;
244	}
