43	/* 调试打印 — 统一使用 syslog 输出到 SD 卡 */
44	#define WATCH_DBG_LOG(fmt, ...) syslog(LOG_INFO, fmt, ##__VA_ARGS__)
45	
46	/****************************************************************************
47	 * Pre-processor Definitions
48	 ****************************************************************************/
49	
50	#define LOGO_DISPLAY_TIME      5000   /* 开机logo最长显示时间(ms)，超时强制切换 */
51	#define ANIMATION_DISPLAY_TIME 5000   /* 开机动画最长显示时间(ms)，超时强制切换 */
52	#define ANIM_CHECK_PERIOD_MS   100    /* 动画播放完成检测周期(ms) */
53	#define LOGO_CHECK_PERIOD_MS   100    /* logo播放完成检测周期(ms) */
54	
55	/* ai_agent 自启动参数（与 packages/ai_agent Makefile 配置对齐） */
56	#define AGENT_TASK_PRIORITY    100
57	#define AGENT_TASK_STACKSIZE   32768
58	
59	/****************************************************************************
60	 * Private Data
61	 ****************************************************************************/
62	
63	typedef enum
64	{
65	  STATE_INIT,            /* 初始状态 */
66	  STATE_SHOW_LOGO,       /* 显示logo状态 */
67	  STATE_SHOW_ANIM,       /* 显示动画状态 */
68	  STATE_SHOW_CLOCK,      /* 显示手表界面状态 */
69	  STATE_DONE             /* 完成状态 */
70	} launcher_state_t;
71	
72	static launcher_state_t current_state = STATE_INIT; /* 当前状态 */
73	static lv_obj_t *content_area = NULL;           /* 内容区域 */
74	static lv_obj_t *current_obj = NULL;            /* 当前显示的对象 */
75	static uint32_t anim_wait_ms = 0;               /* 动画已等待时间(ms) */
76	static uint32_t logo_wait_ms = 0;               /* logo已等待时间(ms) */
77	static ui_mode_t g_boot_ui_mode = UI_MODE_EXPRESSION; /* 本次开机的UI模式 */
78	static int s_wake_attempts = 0;  /* deferred_wake_start_timer 重试计数(运行时切换后可重置) */
79	static lv_timer_t *s_wake_timer = NULL;   /* deferred_wake_start 定时器句柄（停止语音时删除） */
80	static bool g_agent_started = false;      /* ai_agent 任务已拉起（防重入，停止时重置） */
81	
82	/****************************************************************************
83	 * Private Functions
84	 ****************************************************************************/
85	
86	static void anim_check_timer_cb(lv_timer_t *timer);
87	static void logo_check_timer_cb(lv_timer_t *timer);
88	
89	/* 开机卡logo取证心跳：LVGL 主循环存活证据。卡logo时若心跳仍在打印
90	 * 而界面不动 = UI 逻辑问题；心跳停 = 主循环或全系统冻结，取 app.log
91	 * 最后一条日志定位冻结点。前60秒每5秒一跳，之后自删避免常态噪声。 */
92	static void boot_heartbeat_cb(lv_timer_t *timer)
93	{
94	  static int beats = 0;
95	  struct timespec ts;
96	
97	  clock_gettime(CLOCK_MONOTONIC, &ts);
98	  WATCH_DBG_LOG("[LAUNCHER] LVGL alive #%d t=%lus",
99	                ++beats, (unsigned long)ts.tv_sec);
100	
101	  if (beats >= 12)
102	    {
103	      lv_timer_del(timer);
104	    }
105	}
106	
107	/* 空闲超时标志：voice_channel 线程设置，LVGL 定时器轮询并执行 hide */
108	static volatile bool g_idle_timeout_pending = false;
109	
110	/* 小通AI活跃状态检查（避免对话期间黑屏） */
111	extern bool tong_ai_is_active(void);
112	
113	static void on_idle_timeout(void)
114	{
115	  /* 小通AI页面打开时，不隐藏表情页（tong_ai 有自己的音频通路，
116	   * voice_channel 检测不到其语音活动，会误判为空闲） */
117	  if (tong_ai_is_active()) {
118	    return;
119	  }
120	  g_idle_timeout_pending = true;
121	}
122	
123	static void idle_timeout_poll_cb(lv_timer_t *timer)
124	{
125	  if (g_idle_timeout_pending) {
126	    g_idle_timeout_pending = false;
127	    watch_expression_page_hide();
128	  }
129	}
130	
131	/* 唤醒词检测回调：由 voice_channel conversation_thread 调用 */
132	static void on_wake_detected(void)
133	{
134	  /* 在 LVGL 主线程中显示表情 */
135	  lv_async_call((lv_async_cb_t)watch_expression_page_show, NULL);
136	}
137	
138	/**
139	 * @brief 后台拉起 ai_agent 任务（auto 模式：无 CLI，网络就绪后自动开启关键字唤醒）
140	 *
141	 * FLAT build 下 watch 与 ai_agent 同镜像，直接链接 ai_agent_main。
142	 * task_create 非阻塞，不影响 LVGL 主线程。
143	 */
144	static void agent_autostart(void)
145	{
146	  extern int ai_agent_main(int argc, char *argv[]);
147	
148	  if (g_agent_started)
149	    {
150	      return;
151	    }
152	  g_agent_started = true;
153	
154	  /* 注册唤醒词回调 + 空闲超时回调 + LVGL 轮询定时器 */
155	  voice_channel_set_wake_notify(on_wake_detected);
156	  voice_channel_set_idle_timeout_cb(on_idle_timeout);
157	  lv_timer_create(idle_timeout_poll_cb, 2000, NULL);
158	
159	  static char *agent_argv[] = { "auto", NULL };
160	  int pid = task_create("ai_agent", AGENT_TASK_PRIORITY,
161	                        AGENT_TASK_STACKSIZE, ai_agent_main, agent_argv);
162	  if (pid < 0)
163	    {
164	      WATCH_DBG_LOG("[LAUNCHER] ERROR: ai_agent task_create failed: %d", pid);
165	    }
166	  else
167	    {
168	      WATCH_DBG_LOG("[LAUNCHER] ai_agent started (pid=%d, auto mode)", pid);
169	    }
170	}
