172	/**
173	 * @brief 延迟唤醒启动定时器：等 WiFi + ai_agent 都就绪后再启动唤醒监听
174	 */
175	static void deferred_wake_start_timer_cb(lv_timer_t *timer)
176	{
177	    extern bool voice_channel_is_ready(void);
178	    extern int voice_channel_start_wake(void);
179	
180	    bool wifi_ok = settings_wifi_is_connected();
181	    bool voice_ok = voice_channel_is_ready();
182	
183	    WATCH_DBG_LOG("[LAUNCHER] wake start check #%d: wifi=%d voice=%d",
184	                  ++s_wake_attempts, wifi_ok, voice_ok);
185	
186	    if (wifi_ok && voice_ok) {
187	        WATCH_DBG_LOG("[LAUNCHER] both ready, starting wake-word listening");
188	        voice_channel_start_wake();
189	        if (timer == s_wake_timer) {
190	            s_wake_timer = NULL;
191	        }
192	        lv_timer_del(timer);  /* stop this timer */
193	        return;
194	    }
195	
196	    /* After 10s without WiFi (10 attempts × 1s), play no-network alert once */
197	    if (s_wake_attempts == 10) {
198	        tool_system_alert_play(16, 0);
199	    }
200	
201	    /* Safety: give up after 180 attempts (180 seconds) */
202	    if (s_wake_attempts >= 180) {
203	        WATCH_DBG_LOG("[LAUNCHER] wake start timeout, giving up (wifi=%d voice=%d)",
204	                      wifi_ok, voice_ok);
205	        if (timer == s_wake_timer) {
206	            s_wake_timer = NULL;
207	        }
208	        lv_timer_del(timer);
209	    }
210	}
