212	/**
213	 * @brief 运行时切换到表情模式后，启动 ai_agent + 唤醒词监听
214	 *
215	 * 冷启动由 launcher 状态机负责；运行时切换（ui_mode_switch_runtime）
216	 * 跳过了启动流程，需由本函数补齐：拉起 ai_agent + 创建 deferred_wake_start_timer。
217	 * agent_autostart 内部有 static bool started 防重入，重复调用安全。
218	 */
219	void launcher_start_voice_for_expression(void)
220	{
221	  WATCH_DBG_LOG("[LAUNCHER] start voice for expression (runtime switch)");
222	  agent_autostart();
223	  s_wake_attempts = 0;
224	  s_wake_timer = lv_timer_create(deferred_wake_start_timer_cb, 1000, NULL);
225	}
