227	/**
228	 * @brief 运行时切换到手表模式前，停止表情模式的后台任务
229	 *
230	 * 停止语音会话线程、断开 E2E 语音链路，并请求 ai_agent 任务退出
231	 *（同步等待其 teardown 完成，避免切回表情模式时新旧实例并存）。
232	 * 与冷启动进手表模式的行为对齐：手表模式不运行 ai_agent。
233	 * 由 ui_mode_switch_runtime(UI_MODE_WATCH) 调用；再次切回表情模式时
234	 * 由 launcher_start_voice_for_expression() 重新拉起。
235	 */
236	void launcher_stop_voice_for_watch(void)
237	{
238	  extern int voice_channel_stop(void);
239	  extern void volc_e2e_stop(void);
240	  extern void agent_request_shutdown(void);
241	  extern bool agent_is_running(void);
242	
243	  WATCH_DBG_LOG("[LAUNCHER] stop voice+agent for watch (runtime switch)");
244	
245	  /* 取消延迟唤醒定时器，避免 agent 停止后又被它拉起唤醒监听 */
246	  if (s_wake_timer != NULL)
247	    {
248	      lv_timer_del(s_wake_timer);
249	      s_wake_timer = NULL;
250	    }
251	
252	  /* 停语音会话线程：voice_channel_stop 内部 capture_close 解除
253	   * read 阻塞并 join 会话线程；未运行时返回错误，忽略 */
254	  voice_channel_stop();
255	
256	  /* 断开 E2E 语音链路（内部有锁，未建立时安全返回） */
257	  volc_e2e_stop();
258	
259	  /* 请求 ai_agent 退出并同步等待 teardown（主循环 1s 轮询粒度，
260	   *  teardown 含 500ms 的线程退出等待） */
261	  agent_request_shutdown();
262	  int wait_ms = 0;
263	  while (agent_is_running() && wait_ms < 5000)
264	    {
265	      usleep(100 * 1000);
266	      wait_ms += 100;
267	    }
268	  if (agent_is_running())
269	    {
270	      WATCH_DBG_LOG("[LAUNCHER] WARN: ai_agent teardown timeout");
271	    }
272	
273	  /* 允许切回表情模式时重新拉起 */
274	  g_agent_started = false;
275	}
