277	/**
278	 * @brief 切换到下一个状态
279	 */
280	static void goto_next_state(void)
281	{
282	  switch (current_state)
283	    {
284	      case STATE_INIT:
285	        /* 切换到显示logo状态 */
286	        current_state = STATE_SHOW_LOGO;
287	
288	        /* 尽早读取UI模式，选择对应的开机logo。
289	         * 入口日志：ui_mode.json 在 /mnt/spif（littlefs/SPI flash），
290	         * 若卡在读写另一侧实锤 SPI flash 并发死锁。 */
291	        WATCH_DBG_LOG("[LAUNCHER] loading ui_mode.json");
292	        g_boot_ui_mode = ui_mode_load();
293	        ui_mode_set_current(g_boot_ui_mode);
294	        WATCH_DBG_LOG("[LAUNCHER] Boot UI mode: %d (0=expression, 1=watch)",
295	                      (int)g_boot_ui_mode);
296	
297	        /* 恢复上次持久化的音量（/mnt/spif/volume.json），
298	         * 避免重启后回退到板级默认值 */
299	        watch_volume_restore();
300	        WATCH_DBG_LOG("[LAUNCHER] volume restored");
301	
302	        if (current_obj != NULL)
303	          {
304	            lv_obj_del(current_obj);
305	          }
306	
307	        if (g_boot_ui_mode == UI_MODE_WATCH)
308	          {
309	            current_obj = watch_boot_logo_init(content_area);
310	          }
311	        else
312	          {
313	            current_obj = boot_logo_init(content_area);
314	          }
315	        lv_task_handler();
316	        WATCH_DBG_LOG("[LAUNCHER] logo displayed");
317	
318	        /* 周期性检测logo GIF是否播完，播完立即切换（最长等待 LOGO_DISPLAY_TIME） */
319	        logo_wait_ms = 0;
320	        lv_timer_create(logo_check_timer_cb, LOGO_CHECK_PERIOD_MS, NULL);
321	        break;
322	
323	      case STATE_SHOW_LOGO:
324	        /* 切换到显示动画状态 */
325	        current_state = STATE_SHOW_ANIM;
326	        WATCH_DBG_LOG("[LAUNCHER] state: logo done -> animation");
327	
328	        /* 销毁logo并显示动画（根据UI模式选择对应的动画） */
329	        if (g_boot_ui_mode == UI_MODE_WATCH)
330	          {
331	            watch_boot_logo_deinit(current_obj);
332	            current_obj = watch_boot_animation_init(content_area);
333	          }
334	        else
335	          {
336	            boot_logo_deinit(current_obj);
337	            current_obj = boot_animation_init(content_area);
338	          }
339	        lv_task_handler();
340	        WATCH_DBG_LOG("[LAUNCHER] anim displayed");
341	
342	        /* 动画播放期间后台拉起 ai_agent（仅表情UI模式需要）
343	         * 手表UI模式不需要 ai_agent，跳过以加快开机速度 */
344	        if (g_boot_ui_mode == UI_MODE_EXPRESSION)
345	          {
346	            agent_autostart();
347	          }
348	
349	        /* 周期性检测动画是否播完，播完立即切换（最长等待 ANIMATION_DISPLAY_TIME） */
350	        anim_wait_ms = 0;
351	        lv_timer_create(anim_check_timer_cb, ANIM_CHECK_PERIOD_MS, NULL);
352	        break;
353	
354	      case STATE_SHOW_ANIM:
355	        /* 动画播放完成，切换到主界面 */
356	        current_state = STATE_SHOW_CLOCK;
357	        WATCH_DBG_LOG("[LAUNCHER] state: anim done -> main UI");
358	
359	        /* 销毁动画（根据UI模式选择对应的销毁函数） */
360	        if (g_boot_ui_mode == UI_MODE_WATCH)
361	          {
362	            watch_boot_animation_deinit(current_obj);
363	          }
364	        else
365	          {
366	            boot_animation_deinit(current_obj);
367	          }
368	        current_obj = NULL;
369	
370	        /* 根据UI模式进入对应的主界面 */
371	        WATCH_DBG_LOG("[LAUNCHER] Entering UI mode: %d (0=expression, 1=watch)",
372	                      (int)g_boot_ui_mode);
373	
374	        if (g_boot_ui_mode == UI_MODE_WATCH)
375	          {
376	            /* 切换到 vendor watch UI */
377	            watch_switch_to_watch_app(content_area);
378	          }
379	        else
380	          {
381	            /* 默认：表情页面 */
382	            current_obj = (lv_obj_t *)watch_expression_page_init(
383	              content_area);
384	          }
385	        WATCH_DBG_LOG("[LAUNCHER] main UI page ready");
386	
387	        /* 启动电池电量周期监控：开机立即检测一次，之后每60秒检测，
388	         * 电量低于20%时播报低电量语音（watch_battery_check_start 内部
389	         * 有重复调用保护） */
390	        watch_battery_check_start();
391	
392	        /* 仅表情UI模式启动延迟唤醒定时器（手表UI不需要语音唤醒） */
393	        if (g_boot_ui_mode == UI_MODE_EXPRESSION)
394	          {
395	            s_wake_timer = lv_timer_create(deferred_wake_start_timer_cb, 1000, NULL);
396	          }
397	
398	        lv_task_handler();
399	        break;
400	
401	      case STATE_SHOW_CLOCK:
402	        /* 手表界面持续运行，进入完成状态 */
403	        current_state = STATE_DONE;
404	        break;
405	
406	      default:
407	        break;
408	    }
409	}
