411	/**
412	 * @brief 动画播放完成检测定时器回调
413	 *
414	 * GIF播完最后一帧（boot_animation_is_finished）后立即切换到表情页面；
415	 * 超过 ANIMATION_DISPLAY_TIME 未播完则强制切换，避免一直停留在动画页。
416	 */
417	static void anim_check_timer_cb(lv_timer_t *timer)
418	{
419	  anim_wait_ms += ANIM_CHECK_PERIOD_MS;
420	
421	  /* 根据UI模式检查对应的动画是否播放完成 */
422	  bool finished = (g_boot_ui_mode == UI_MODE_WATCH)
423	    ? watch_boot_animation_is_finished()
424	    : boot_animation_is_finished();
425	
426	  if (finished || anim_wait_ms >= ANIMATION_DISPLAY_TIME)
427	    {
428	      if (!finished)
429	        {
430	          WATCH_DBG_LOG("[LAUNCHER] anim GIF unfinished after %ums, "
431	                        "forcing switch", anim_wait_ms);
432	        }
433	      lv_timer_del(timer);
434	      goto_next_state();
435	    }
436	}
437	
438	/**
439	 * @brief logo播放完成检测定时器回调
440	 *
441	 * GIF播完最后一帧（boot_logo_is_finished）后立即切换到动画页面；
442	 * 超过 LOGO_DISPLAY_TIME 未播完则强制切换，避免一直停留在logo页。
443	 */
444	static void logo_check_timer_cb(lv_timer_t *timer)
445	{
446	  logo_wait_ms += LOGO_CHECK_PERIOD_MS;
447	
448	  /* 根据UI模式检查对应的logo是否播放完成 */
449	  bool finished = (g_boot_ui_mode == UI_MODE_WATCH)
450	    ? watch_boot_logo_is_finished()
451	    : boot_logo_is_finished();
452	
453	  if (finished || logo_wait_ms >= LOGO_DISPLAY_TIME)
454	    {
455	      if (!finished)
456	        {
457	          WATCH_DBG_LOG("[LAUNCHER] logo GIF unfinished after %ums, "
458	                        "forcing switch", logo_wait_ms);
459	        }
460	      lv_timer_del(timer);
461	      goto_next_state();
462	    }
463	}
