190	const lv_font_t* watch_resource_get_font(const char* key)
191	{
192	    /* 搜索已创建的字体 */
193	    for (int i = 0; i < (int)ARRAY_SIZE(g_font_resource_map); i++) {
194	        if (g_font_resource_map[i].font != LV_FONT_DEFAULT &&
195	            lv_strcmp(key, g_font_resource_map[i].key) == 0) {
196	            return g_font_resource_map[i].font;
197	        }
198	    }
199	
200	    /* 字体未预创建 — 解析 key "<name>_<size>" 并动态创建 */
201	    const char *last_underscore = strrchr(key, '_');
202	    if (last_underscore == NULL) {
203	        return LV_FONT_DEFAULT;
204	    }
205	
206	    int size = atoi(last_underscore + 1);
207	    if (size <= 0 || size > 200) {
208	        return LV_FONT_DEFAULT;
209	    }
210	
211	    /* 提取字体名 */
212	    size_t name_len = last_underscore - key;
213	    char font_name[64];
214	    if (name_len >= sizeof(font_name)) name_len = sizeof(font_name) - 1;
215	    memcpy(font_name, key, name_len);
216	    font_name[name_len] = '\0';
217	
218	    /* 查找嵌入式字体数据 */
219	    const uint8_t *font_data = NULL;
220	    uint32_t font_data_size = 0;
221	    for (int i = 0; i < (int)ARRAY_SIZE(g_font_data_map); i++) {
222	        if (strcmp(g_font_data_map[i].name, font_name) == 0) {
223	            font_data = g_font_data_map[i].data;
224	            font_data_size = g_font_data_map[i].size;
225	            break;
226	        }
227	    }
228	
229	    if (font_data == NULL) {
230	        return LV_FONT_DEFAULT;
231	    }
232	
233	    /* 动态创建 FreeType 字体 */
234	    lv_fs_path_ex_t mempath;
235	    lv_fs_make_path_from_buffer(&mempath, 'M', font_data, font_data_size);
236	    lv_font_t *font = lv_freetype_font_create((const char *)&mempath,
237	        LV_FREETYPE_FONT_RENDER_MODE_BITMAP,
238	        size,
239	        LV_FREETYPE_FONT_STYLE_NORMAL);
240	    if (font) {
241	        return font;
242	    }
243	
244	    return LV_FONT_DEFAULT;
245	}
