63	void lv_gifdec_start(void * ctx, const void * src)
64	{
65	    lv_gifdec_t * dec_ctx = (lv_gifdec_t *)ctx;
66	
67	    /*Close previous gif if any*/
68	    if(dec_ctx->gif) {
69	        lv_image_cache_drop(lv_image_get_src(dec_ctx->obj));
70	
71	        gd_close_gif(dec_ctx->gif);
72	        dec_ctx->gif = NULL;
73	        dec_ctx->imgdsc.data = NULL;
74	    }
75	
76	    if(lv_image_src_get_type(src) == LV_IMAGE_SRC_VARIABLE) {
77	        const lv_image_dsc_t * img_dsc = src;
78	        dec_ctx->gif = gd_open_gif_data(img_dsc->data);
79	    }
80	    else if(lv_image_src_get_type(src) == LV_IMAGE_SRC_FILE) {
81	        dec_ctx->gif = gd_open_gif_file(src);
82	    }
83	    if(dec_ctx->gif == NULL) {
84	        LV_LOG_WARN("Couldn't load the source");
85	        return;
86	    }
87	
88	    dec_ctx->imgdsc.data = dec_ctx->gif->canvas;
89	    dec_ctx->imgdsc.header.cf = LV_COLOR_FORMAT_ARGB8888;
90	    dec_ctx->imgdsc.header.h = dec_ctx->gif->height;
91	    dec_ctx->imgdsc.header.w = dec_ctx->gif->width;
92	    dec_ctx->imgdsc.data_size = dec_ctx->gif->height * dec_ctx->gif->width * 4;
93	    dec_ctx->last_call = lv_tick_get();
94	
95	    lv_image_set_src(dec_ctx->obj, &dec_ctx->imgdsc);
96	
97	    lv_timer_resume(dec_ctx->timer);
98	    lv_timer_reset(dec_ctx->timer);
99	
100	    lv_gifdec_frame_cb(dec_ctx->timer);
101	}
102	
103	void lv_gifdec_pause(void * ctx)
104	{
105	    lv_gifdec_t * dec_ctx = (lv_gifdec_t *)ctx;
106	    lv_timer_pause(dec_ctx->timer);
107	}
108	
109	void lv_gifdec_resume(void * ctx)
110	{
111	    lv_gifdec_t * dec_ctx = (lv_gifdec_t *)ctx;
112	
113	    if(dec_ctx->gif == NULL) {
114	        LV_LOG_WARN("Gif resource not loaded correctly");
115	        return;
116	    }
117	
118	    lv_timer_resume(dec_ctx->timer);
119	}
120	
121	void lv_gifdec_restart(void * ctx)
122	{
123	    lv_gifdec_t * dec_ctx = (lv_gifdec_t *)ctx;
124	
125	    if(dec_ctx->gif == NULL) {
126	        LV_LOG_WARN("Gif resource not loaded correctly");
127	        return;
128	    }
129	
130	    gd_rewind(dec_ctx->gif);
131	    lv_timer_resume(dec_ctx->timer);
132	    lv_timer_reset(dec_ctx->timer);
133	}
134	
135	void lv_gifdec_close(void * ctx)
136	{
137	    lv_gifdec_t * dec_ctx = (lv_gifdec_t *)ctx;
138	
139	    lv_image_cache_drop(lv_image_get_src(dec_ctx->obj));
140	
141	    if(dec_ctx->gif)
142	        gd_close_gif(dec_ctx->gif);
143	    lv_timer_delete(dec_ctx->timer);
144	    lv_free(dec_ctx);
145	}
146	
147	bool lv_gifdec_get_size(const char * src, uint16_t * w, uint16_t * h)
148	{
149	    bool res = false;
150	    gd_GIF * gif = gd_open_gif_file(src);
151	    if(gif != NULL) {
152	        *w = gif->width;
153	        *h = gif->height;
154	        gd_close_gif(gif);
155	        res = true;
156	    }
157	    else {
158	        *w = 0;
159	        *h = 0;
160	    }
161	    return res;
162	}
