164	/**********************
165	 *   STATIC FUNCTIONS
166	 **********************/
167	
168	static void lv_gifdec_frame_cb(lv_timer_t * t)
169	{
170	    lv_gifdec_t * dec_ctx = (lv_gifdec_t *)t->user_data;
171	
172	    uint32_t elaps = lv_tick_elaps(dec_ctx->last_call);
173	    if(elaps < dec_ctx->gif->gce.delay * 10) return;
174	
175	    dec_ctx->last_call = lv_tick_get();
176	
177	    int has_next = gd_get_frame(dec_ctx->gif);
178	    if(has_next == 0) {
179	        /*It was the last repeat*/
180	        lv_result_t res = lv_obj_send_event(dec_ctx->obj, LV_EVENT_READY, NULL);
181	        lv_timer_pause(t);
182	        if(res != LV_FS_RES_OK) return;
183	    }
184	
185	    gd_render_frame(dec_ctx->gif, (uint8_t *)dec_ctx->imgdsc.data);
186	
187	    lv_image_cache_drop(lv_image_get_src(dec_ctx->obj));
188	    lv_obj_invalidate(dec_ctx->obj);
189	}
