49	
50	/* Long press duration in milliseconds (10 seconds) */
51	#define LONG_PRESS_DURATION_MS  10000
52	
53	/* Short press duration in milliseconds (100ms) */
54	#define SHORT_PRESS_DURATION_MS 100
55	
56	/* 调试打印 — 统一使用 syslog 输出到 SD 卡 */
