62	/* Debounce threshold: require N consecutive consistent readings */
63	#define DEBOUNCE_THRESHOLD      5
64	
65	/****************************************************************************
66	 * Private Types
67	 ****************************************************************************/
68	
69	enum button_state_e
70	{
71	  BUTTON_STATE_NOT_PRESSED = 0,
72	  BUTTON_STATE_SHORT_PRESS = 1,
73	  BUTTON_STATE_LONG_PRESS  = 2
74	};
75	
76	enum button_type_e
77	{
78	  BUTTON_TYPE_BOOT = 0,
79	  BUTTON_TYPE_PWR  = 1
80	};
81	
82	struct button_context_s
83	{
84	  enum button_type_e type;
85	  int gpio;
86	  bool active_low;
87	  bool last_state;
88	  bool is_pressed;
89	  clock_t press_start_time;
90	  enum button_state_e state;
91	  bool debounced_pressed;
92	  uint8_t debounce_count;
93	};
94	
95	/****************************************************************************
96	 * Private Data
97	 ****************************************************************************/
98	
99	static struct button_context_s g_boot_button;
100	static struct button_context_s g_pwr_button;
101	static lv_timer_t *g_button_timer = NULL;
102	/* static bool g_settings_active = false; */  /* 表情UI设置界面已禁用 */
103	static bool g_mic_muted = false;        /* 禁麦状态：false=开麦, true=禁麦 */
104	
105	/****************************************************************************
106	 * Private Functions
107	 ****************************************************************************/
108	
109	static bool button_get_gpio_state(struct button_context_s *ctx)
110	{
111	  bool gpio_value;
112	  bool pressed;
113	
114	  gpio_value = esp32s3_gpioread(ctx->gpio);
115	
116	  if (ctx->active_low)
117	    {
118	      pressed = !gpio_value;
119	    }
120	  else
121	    {
122	      pressed = gpio_value;
123	    }
124	
125	  return pressed;
126	}
127	
128	static void button_ctx_init(struct button_context_s *ctx,
129	                            enum button_type_e type,
130	                            int gpio,
131	                            bool active_low)
132	{
133	  ctx->type = type;
134	  ctx->gpio = gpio;
135	  ctx->active_low = active_low;
136	  ctx->last_state = false;
137	  ctx->is_pressed = false;
138	  ctx->press_start_time = 0;
139	  ctx->state = BUTTON_STATE_NOT_PRESSED;
140	  ctx->debounced_pressed = false;
141	  ctx->debounce_count = 0;
142	
143	  if (active_low)
144	    {
145	      esp32s3_configgpio(gpio, INPUT_PULLUP);
146	    }
147	  else
148	    {
149	      esp32s3_configgpio(gpio, INPUT_PULLDOWN);
150	    }
151	}
152	
153	static enum button_state_e button_update(struct button_context_s *ctx)
154	{
155	  bool current_pressed;
156	  bool raw_pressed;
157	  clock_t current_time;
158	  clock_t elapsed_ms;
159	
160	  current_time = clock();
161	  raw_pressed = button_get_gpio_state(ctx);
162	
163	  /* Software debounce */
164	  if (raw_pressed == ctx->debounced_pressed)
165	    {
166	      ctx->debounce_count = 0;
167	    }
168	  else
169	    {
170	      ctx->debounce_count++;
171	      if (ctx->debounce_count >= DEBOUNCE_THRESHOLD)
172	        {
173	          ctx->debounced_pressed = raw_pressed;
174	          ctx->debounce_count = 0;
175	        }
176	    }
177	
178	  current_pressed = ctx->debounced_pressed;
179	
180	  /* Detect button press event */
181	  if (current_pressed && !ctx->last_state)
182	    {
183	      ctx->is_pressed = true;
184	      ctx->press_start_time = current_time;
185	      ctx->state = BUTTON_STATE_NOT_PRESSED;
186	    }
187	  /* Detect button release event */
188	  else if (!current_pressed && ctx->last_state)
189	    {
190	      if (ctx->is_pressed)
191	        {
192	          elapsed_ms = (current_time - ctx->press_start_time) * 1000 / CLOCKS_PER_SEC;
193	
194	          if (elapsed_ms >= LONG_PRESS_DURATION_MS)
195	            {
196	              ctx->state = BUTTON_STATE_LONG_PRESS;
197	            }
198	          else if (elapsed_ms >= SHORT_PRESS_DURATION_MS)
199	            {
200	              ctx->state = BUTTON_STATE_SHORT_PRESS;
201	            }
202	          else
203	            {
204	              ctx->state = BUTTON_STATE_NOT_PRESSED;
205	            }
206	        }
207	
208	      ctx->is_pressed = false;
209	    }
210	  /* Check for long press while button is still held */
211	  else if (current_pressed && ctx->is_pressed)
212	    {
213	      elapsed_ms = (current_time - ctx->press_start_time) * 1000 / CLOCKS_PER_SEC;
214	
215	      if (elapsed_ms >= LONG_PRESS_DURATION_MS)
216	        {
217	          ctx->state = BUTTON_STATE_LONG_PRESS;
218	        }
219	    }
220	
221	  ctx->last_state = current_pressed;
222	  return ctx->state;
223	}
