225	/****************************************************************************
226	 * Name: handle_boot_short_press
227	 *
228	 * Description:
229	 *   BOOT短按处理：硬件静音/取消静音（不掉语音通道，不阻塞LVGL）
230	 ****************************************************************************/
231	
232	static void handle_boot_short_press(void)
233	{
234	  BTN_LOG("[BTN] BOOT short press detected\n");
235	
236	  g_mic_muted = !g_mic_muted;
237	  if (g_mic_muted) {
238	    voice_channel_enable_wake_gate();  /* 立即上锁，禁止噪声触发LLM */
239	    /* Defer I2C mute to voice_channel thread — calling es7210_set_mic_mute
240	     * from LVGL timer races with audio driver I2C access and can deadlock. */
241	    voice_channel_request_mic_mute(true);
242	    watch_expression_page_set_face("sleepy", 0);
243	    BTN_LOG("[BTN] Mic muted (via voice thread) — face=sleepy\n");
244	  } else {
245	    voice_channel_request_mic_mute(false);
246	    voice_channel_enable_wake_gate();  /* 重新要求唤醒词 */
247	    /* face 由 voice_channel 状态机自动管理 (listening/thinking/speaking) */
248	    BTN_LOG("[BTN] Mic unmuted (via voice thread) — wake gate enabled\n");
249	  }
250	}
