316	/****************************************************************************
317	 * Name: button_monitor_timer_cb
318	 *
319	 * Description:
320	 *   LVGL定时器回调：轮询按键状态并处理事件
321	 ****************************************************************************/
322	
323	static void button_monitor_timer_cb(lv_timer_t *timer)
324	{
325	  enum button_state_e boot_state;
326	  enum button_state_e pwr_state;
327	  static enum button_state_e last_boot_state = BUTTON_STATE_NOT_PRESSED;
328	  static enum button_state_e last_pwr_state = BUTTON_STATE_NOT_PRESSED;
329	
330	  (void)timer;
331	
332	  /* Update button states */
333	  boot_state = button_update(&g_boot_button);
334	  pwr_state = button_update(&g_pwr_button);
335	
336	  /* Handle BOOT button events */
337	  if (boot_state != last_boot_state)
338	    {
339	      if (boot_state == BUTTON_STATE_LONG_PRESS)
340	        {
341	          handle_boot_long_press();
342	        }
343	      else if (boot_state == BUTTON_STATE_SHORT_PRESS)
344	        {
345	          handle_boot_short_press();
346	        }
347	      last_boot_state = boot_state;
348	    }
349	
350	  /* Handle PWR button events */
351	  if (pwr_state != last_pwr_state)
352	    {
353	      if (pwr_state == BUTTON_STATE_SHORT_PRESS)
354	        {
355	          handle_pwr_short_press();
356	        }
357	      else if (pwr_state == BUTTON_STATE_LONG_PRESS)
358	        {
359	          /* PWR长按也可以返回主页 */
360	          handle_pwr_short_press();
361	        }
362	      last_pwr_state = pwr_state;
363	    }
364	}
365	
366	/****************************************************************************
367	 * Public Functions
368	 ****************************************************************************/
369	
370	void watch_button_monitor_init(void)
371	{
372	  BTN_LOG("Initializing button monitor...");
373	
374	  /* Initialize buttons */
375	  button_ctx_init(&g_boot_button, BUTTON_TYPE_BOOT, BOOT_BUTTON_GPIO, true);
376	  button_ctx_init(&g_pwr_button, BUTTON_TYPE_PWR, PWR_BUTTON_GPIO, false);
377	
378	  /* Create LVGL timer for polling (runs in main thread, safe for LVGL calls) */
379	  g_button_timer = lv_timer_create(button_monitor_timer_cb, POLL_INTERVAL_MS, NULL);
380	  if (g_button_timer == NULL)
381	    {
382	      BTN_LOG("ERROR: Failed to create button monitor timer");
383	      return;
384	    }
385	
386	  BTN_LOG("Button monitor started (BOOT=GPIO%d, PWR=GPIO%d)",
387	          BOOT_BUTTON_GPIO, PWR_BUTTON_GPIO);
388	}
