1	/**
2	 * @file volume_control.c
3	 * 音量控制模块实现
4	 *
5	 * 通过 ESP32-S3 I2S + ES8311 音频编解码器控制硬件音量。
6	 * 百分比 10-100% 线性映射到硬件范围 100-1000（<10% 视为静音=0）。
7	 */
8	
9	#include <nuttx/config.h>
10	#include <stdio.h>
11	#include <stdlib.h>
12	#include <string.h>
13	#include <unistd.h>
14	#include <stdbool.h>
15	#include <math.h>
16	
17	#include <arch/board/board.h>
18	#include <syslog.h>
19	
20	#include "volume_control.h"
21	
22	/****************************************************************************
23	 * Pre-processor Definitions
24	 ****************************************************************************/
25	
26	#define VOL_TAG "[VOLUME] "
27	/* 调试打印 — 统一使用 syslog 输出到 SD 卡 */
28	#define VOL_LOG(fmt, ...) syslog(LOG_INFO, VOL_TAG fmt, ##__VA_ARGS__)
29	
30	#define WATCH_VOLUME_PERCENT_MIN  10
31	#define WATCH_VOLUME_PERCENT_MAX 100
32	#define WATCH_VOLUME_HW_MIN      100   /* hardware value for 10% */
33	#define WATCH_VOLUME_HW_MAX     1000   /* hardware value for 100% */
34	
35	/* 音量持久化 —— /mnt/spif/volume.json，格式: {"volume":<hw 0-1000>}
36	 * 仿照 ui_mode_manager 的 JSON 持久化：板级 g_watch_volume 每次开机
37	 * 都会重置为 Kconfig 默认值，需在此保存并在开机时恢复
38	 *（watch_volume_restore，由 launcher 调用）。 */
39	#define VOLUME_CONFIG_FILE  "/mnt/spif/volume.json"
40	#define VOLUME_CONFIG_KEY   "\"volume\":"
41	
42	/****************************************************************************
43	 * Private Data
44	 ****************************************************************************/
45	
46	static const int s_volume_levels[5] = {0, 250, 500, 750, 1000};
47	
48	/****************************************************************************
49	 * Private Functions — persistence
50	 ****************************************************************************/
51	
52	/* 保存硬件音量值到 /mnt/spif/volume.json（{"volume":%d}） */
53	static void watch_volume_save(int value)
54	{
55	  FILE *fp = fopen(VOLUME_CONFIG_FILE, "w");
56	  if (fp == NULL)
57	    {
58	      return;
59	    }
60	  fprintf(fp, "{\"volume\":%d}\n", value);
61	  fclose(fp);
62	}
63	
64	/* 读取持久化的硬件音量值；文件不存在或内容非法时返回 -1 */
65	static int watch_volume_load(void)
66	{
67	  char buf[64];
68	  int value = -1;
69	
70	  FILE *fp = fopen(VOLUME_CONFIG_FILE, "r");
71	  if (fp == NULL)
72	    {
73	      return -1;
74	    }
75	
76	  if (fgets(buf, sizeof(buf), fp) != NULL)
77	    {
78	      char *key_pos = strstr(buf, VOLUME_CONFIG_KEY);
79	      if (key_pos != NULL)
80	        {
81	          value = atoi(key_pos + strlen(VOLUME_CONFIG_KEY));
82	        }
83	    }
84	  fclose(fp);
85	
86	  if (value < 0 || value > WATCH_VOLUME_HW_MAX)
87	    {
88	      value = -1;
89	    }
90	  return value;
91	}
92	
93	/****************************************************************************
94	 * Public Functions — Percent API
95	 ****************************************************************************/
96	
97	/* Square-law mapping from percent to hardware value.
98	 * Spreads the quiet range and compresses the loud end to match
99	 * human loudness perception.
100	 *
101	 *   hw = 1000 * (pct / 100)^2     (0% → 0, 100% → 1000)
102	 *
103	 *   pct   0%   10%   20%   30%   50%   70%   100%
104	 *   hw     0    10    40    90   250   490   1000
105	 *   DAC    0    85   136   166   204   229    255
106	 */
107	static int percent_to_hw(int percent)
108	{
109	  if (percent <= 0)
110	    {
111	      return 0;
112	    }
113	  if (percent >= WATCH_VOLUME_PERCENT_MAX)
114	    {
115	      return WATCH_VOLUME_HW_MAX;
116	    }
117	  /* k = 2.0: hw ∝ percent^2 */
118	  return (int)((int64_t)WATCH_VOLUME_HW_MAX * percent * percent /
119	               (100 * 100));
120	}
121	
122	/* Inverse: sqrt of hardware proportion */
123	static int hw_to_percent(int value)
124	{
125	  if (value <= 0)
126	    {
127	      return 0;
128	    }
129	  if (value >= WATCH_VOLUME_HW_MAX)
130	    {
131	      return WATCH_VOLUME_PERCENT_MAX;
132	    }
133	  return (int)(100.0f * sqrtf((float)value / WATCH_VOLUME_HW_MAX));
134	}
135	
136	int watch_volume_set_percent(int percent)
137	{
138	  int hw = percent_to_hw(percent);
139	  int ret = watch_volume_set_value(hw);
140	  VOL_LOG("Set percent %d%% → hw=%d (ret=%d)", percent, hw, ret);
141	  return (ret == 0) ? 0 : -1;
142	}
143	
144	int watch_volume_get_percent(void)
145	{
146	#if defined(CONFIG_ESP32S3_I2S) && defined(CONFIG_AUDIO_ES8311)
147	  uint16_t vol = 0;
148	  if (esp32s3_watch_audio_getvolume(&vol) != OK)
149	    {
150	      return -1;
151	    }
152	  return hw_to_percent((int)vol);
153	#else
154	  return -1;
155	#endif
156	}
157	
158	int watch_volume_step_delta(int delta)
159	{
160	  int pct = watch_volume_get_percent();
161	  if (pct < 0)
162	    {
163	      return -1;
164	    }
165	  pct += delta;
166	  if (pct < WATCH_VOLUME_PERCENT_MIN)
167	    {
168	      pct = WATCH_VOLUME_PERCENT_MIN;
169	    }
170	  if (pct > WATCH_VOLUME_PERCENT_MAX)
171	    {
172	      pct = WATCH_VOLUME_PERCENT_MAX;
173	    }
174	  watch_volume_set_percent(pct);
175	  return pct;
176	}
