230	{
231	#if defined(CONFIG_ESP32S3_I2S) && defined(CONFIG_AUDIO_ES8311)
232	  if (value < 0)   value = 0;
233	  if (value > 1000) value = 1000;
234	  int ret = esp32s3_watch_audio_setvolume((uint16_t)value);
235	  VOL_LOG("Set volume to %d (ret=%d)", value, ret);
236	  if (ret == OK)
