249	{
250	#if defined(CONFIG_ESP32S3_I2S) && defined(CONFIG_AUDIO_ES8311)
251	  int value = watch_volume_load();
252	  if (value < 0)
253	    {
254	      /* 无保存值，保持板级默认音量 */
255	      return -1;
256	    }
257	  /* 直接写硬件 + 板级缓存，不回写文件（值未变化） */
258	  int ret = esp32s3_watch_audio_setvolume((uint16_t)value);
259	  VOL_LOG("Restore volume to %d (ret=%d)", value, ret);
260	  return (ret == OK) ? 0 : -1;
261	#else
262	  return -1;
263	#endif
