76	static gd_GIF * gif_open(gd_GIF * gif_base)
77	{
78	    uint8_t sigver[3];
79	    uint16_t width, height, depth;
80	    uint8_t fdsz, bgidx, aspect;
81	    uint8_t * bgcolor;
82	    int gct_sz;
83	    gd_GIF * gif = NULL;
84	
85	    /* Header */
86	    f_gif_read(gif_base, sigver, 3);
87	    if(memcmp(sigver, "GIF", 3) != 0) {
88	        LV_LOG_WARN("invalid signature\n");
89	        goto fail;
90	    }
91	    /* Version */
92	    f_gif_read(gif_base, sigver, 3);
93	    if(memcmp(sigver, "89a", 3) != 0) {
94	        LV_LOG_WARN("invalid version\n");
95	        goto fail;
96	    }
97	    /* Width x Height */
98	    width  = read_num(gif_base);
99	    height = read_num(gif_base);
100	    /* FDSZ */
101	    f_gif_read(gif_base, &fdsz, 1);
102	    /* Presence of GCT */
103	    if(!(fdsz & 0x80)) {
104	        LV_LOG_WARN("no global color table\n");
105	        goto fail;
106	    }
107	    /* Color Space's Depth */
108	    depth = ((fdsz >> 4) & 7) + 1;
109	    /* Ignore Sort Flag. */
110	    /* GCT Size */
111	    gct_sz = 1 << ((fdsz & 0x07) + 1);
112	    /* Background Color Index */
113	    f_gif_read(gif_base, &bgidx, 1);
114	    /* Aspect Ratio */
115	    f_gif_read(gif_base, &aspect, 1);
116	    /* Create gd_GIF Structure. */
117	#if LV_GIF_CACHE_DECODE_DATA
118	    gif = lv_malloc(sizeof(gd_GIF) + 5 * width * height + LZW_CACHE_SIZE);
119	    #else
120	    gif = lv_malloc(sizeof(gd_GIF) + 5 * width * height);
121	    #endif
122	    if(!gif) goto fail;
123	    memcpy(gif, gif_base, sizeof(gd_GIF));
124	    gif->width  = width;
125	    gif->height = height;
126	    gif->depth  = depth;
127	    /* Read GCT */
128	    gif->gct.size = gct_sz;
129	    f_gif_read(gif, gif->gct.colors, 3 * gif->gct.size);
130	    gif->palette = &gif->gct;
131	    gif->bgindex = bgidx;
132	    gif->canvas = (uint8_t *) &gif[1];
133	    gif->frame = &gif->canvas[4 * width * height];
134	    if(gif->bgindex) {
135	        memset(gif->frame, gif->bgindex, gif->width * gif->height);
136	    }
137	    bgcolor = &gif->palette->colors[gif->bgindex * 3];
138	    #if LV_GIF_CACHE_DECODE_DATA
139	    gif->lzw_cache = gif->frame + width * height;
140	    #endif
141	
142	#ifdef GIFDEC_FILL_BG
143	    GIFDEC_FILL_BG(gif->canvas, gif->width * gif->height, 1, gif->width * gif->height, bgcolor, 0xff);
144	#else
145	    for(int i = 0; i < gif->width * gif->height; i++) {
146	        gif->canvas[i * 4 + 0] = *(bgcolor + 2);
147	        gif->canvas[i * 4 + 1] = *(bgcolor + 1);
148	        gif->canvas[i * 4 + 2] = *(bgcolor + 0);
149	        gif->canvas[i * 4 + 3] = 0xff;
150	    }
151	#endif
152	    gif->anim_start = f_gif_seek(gif, 0, LV_FS_SEEK_CUR);
153	    gif->loop_count = -1;
154	    goto ok;
155	fail:
156	    f_gif_close(gif_base);
157	ok:
158	    return gif;
159	}
