161	static void
162	discard_sub_blocks(gd_GIF * gif)
163	{
164	    uint8_t size;
165	
166	    do {
167	        f_gif_read(gif, &size, 1);
168	        f_gif_seek(gif, size, LV_FS_SEEK_CUR);
169	    } while(size);
170	}
171	
172	static void
173	read_plain_text_ext(gd_GIF * gif)
174	{
175	    if(gif->plain_text) {
176	        uint16_t tx, ty, tw, th;
177	        uint8_t cw, ch, fg, bg;
178	        size_t sub_block;
179	        f_gif_seek(gif, 1, LV_FS_SEEK_CUR); /* block size = 12 */
180	        tx = read_num(gif);
181	        ty = read_num(gif);
182	        tw = read_num(gif);
183	        th = read_num(gif);
184	        f_gif_read(gif, &cw, 1);
185	        f_gif_read(gif, &ch, 1);
186	        f_gif_read(gif, &fg, 1);
187	        f_gif_read(gif, &bg, 1);
188	        sub_block = f_gif_seek(gif, 0, LV_FS_SEEK_CUR);
189	        gif->plain_text(gif, tx, ty, tw, th, cw, ch, fg, bg);
190	        f_gif_seek(gif, sub_block, LV_FS_SEEK_SET);
191	    }
192	    else {
193	        /* Discard plain text metadata. */
194	        f_gif_seek(gif, 13, LV_FS_SEEK_CUR);
195	    }
196	    /* Discard plain text sub-blocks. */
197	    discard_sub_blocks(gif);
198	}
199	
200	static void
201	read_graphic_control_ext(gd_GIF * gif)
202	{
203	    uint8_t rdit;
204	
205	    /* Discard block size (always 0x04). */
206	    f_gif_seek(gif, 1, LV_FS_SEEK_CUR);
207	    f_gif_read(gif, &rdit, 1);
208	    gif->gce.disposal = (rdit >> 2) & 3;
209	    gif->gce.input = rdit & 2;
210	    gif->gce.transparency = rdit & 1;
211	    gif->gce.delay = read_num(gif);
212	    f_gif_read(gif, &gif->gce.tindex, 1);
213	    /* Skip block terminator. */
214	    f_gif_seek(gif, 1, LV_FS_SEEK_CUR);
215	}
216	
217	static void
218	read_comment_ext(gd_GIF * gif)
219	{
220	    if(gif->comment) {
221	        size_t sub_block = f_gif_seek(gif, 0, LV_FS_SEEK_CUR);
222	        gif->comment(gif);
223	        f_gif_seek(gif, sub_block, LV_FS_SEEK_SET);
224	    }
225	    /* Discard comment sub-blocks. */
226	    discard_sub_blocks(gif);
227	}
228	
229	static void
230	read_application_ext(gd_GIF * gif)
231	{
232	    char app_id[8];
233	    char app_auth_code[3];
234	    uint16_t loop_count;
235	
236	    /* Discard block size (always 0x0B). */
237	    f_gif_seek(gif, 1, LV_FS_SEEK_CUR);
238	    /* Application Identifier. */
239	    f_gif_read(gif, app_id, 8);
240	    /* Application Authentication Code. */
241	    f_gif_read(gif, app_auth_code, 3);
242	    if(!strncmp(app_id, "NETSCAPE", sizeof(app_id))) {
243	        /* Discard block size (0x03) and constant byte (0x01). */
244	        f_gif_seek(gif, 2, LV_FS_SEEK_CUR);
245	        loop_count = read_num(gif);
246	        if(gif->loop_count < 0) {
247	            if(loop_count == 0) {
248	                gif->loop_count = 0;
249	            }
250	            else {
251	                gif->loop_count = loop_count + 1;
252	            }
253	        }
254	        /* Skip block terminator. */
255	        f_gif_seek(gif, 1, LV_FS_SEEK_CUR);
256	    }
257	    else if(gif->application) {
258	        size_t sub_block = f_gif_seek(gif, 0, LV_FS_SEEK_CUR);
259	        gif->application(gif, app_id, app_auth_code);
260	        f_gif_seek(gif, sub_block, LV_FS_SEEK_SET);
261	        discard_sub_blocks(gif);
262	    }
263	    else {
264	        discard_sub_blocks(gif);
265	    }
266	}
267	
268	static void
269	read_ext(gd_GIF * gif)
270	{
271	    uint8_t label;
272	
273	    f_gif_read(gif, &label, 1);
274	    switch(label) {
275	        case 0x01:
276	            read_plain_text_ext(gif);
277	            break;
278	        case 0xF9:
279	            read_graphic_control_ext(gif);
280	            break;
281	        case 0xFE:
282	            read_comment_ext(gif);
283	            break;
284	        case 0xFF:
285	            read_application_ext(gif);
286	            break;
287	        default:
288	            LV_LOG_WARN("unknown extension: %02X\n", label);
289	    }
290	}
291	
292	static uint16_t
293	get_key(gd_GIF *gif, int key_size, uint8_t *sub_len, uint8_t *shift, uint8_t *byte)
294	{
295	    int bits_read;
296	    int rpad;
297	    int frag_size;
298	    uint16_t key;
299	
300	    key = 0;
301	    for (bits_read = 0; bits_read < key_size; bits_read += frag_size) {
302	        rpad = (*shift + bits_read) % 8;
303	        if (rpad == 0) {
304	            /* Update byte. */
305	            if (*sub_len == 0) {
306	                f_gif_read(gif, sub_len, 1); /* Must be nonzero! */
307	                if (*sub_len == 0) return 0x1000;
308	            }
309	            f_gif_read(gif, byte, 1);
310	            (*sub_len)--;
311	        }
312	        frag_size = MIN(key_size - bits_read, 8 - rpad);
313	        key |= ((uint16_t) ((*byte) >> rpad)) << bits_read;
314	    }
315	    /* Clear extra bits to the left. */
316	    key &= (1 << key_size) - 1;
317	    *shift = (*shift + key_size) % 8;
318	    return key;
319	}
