321	#if LV_GIF_CACHE_DECODE_DATA
322	static int
323	read_image_data(gd_GIF *gif, int interlace)
324	{
325	    uint8_t sub_len, shift, byte;
326	    int ret = 0;
327	    int key_size;
328	    int y, pass, linesize;
329	    uint8_t *ptr = NULL;
330	    uint8_t *ptr_row_start = NULL;
331	    uint8_t *ptr_base = NULL;
332	    size_t start, end;
333	    uint16_t key, clear_code, stop_code, curr_code;
334	    int frm_off, frm_size,curr_size,top_slot,new_codes,slot;
335	    /* The first value of the value sequence corresponding to key */
336	    int first_value;
337	    int last_key;
338	    uint8_t *sp = NULL;
339	    uint8_t *p_stack = NULL;
340	    uint8_t *p_suffix = NULL;
341	    uint16_t *p_prefix = NULL;
342	
343	    /* get initial key size and clear code, stop code */
344	    f_gif_read(gif, &byte, 1);
345	    key_size = (int) byte;
346	    clear_code = 1 << key_size;
347	    stop_code = clear_code + 1;
348	    key = 0;
349	
350	    start = f_gif_seek(gif, 0, LV_FS_SEEK_CUR);
351	    discard_sub_blocks(gif);
352	    end = f_gif_seek(gif, 0, LV_FS_SEEK_CUR);
353	    f_gif_seek(gif, start, LV_FS_SEEK_SET);
354	
355	    linesize = gif->width;
356	    ptr_base = &gif->frame[gif->fy * linesize + gif->fx];
357	    ptr_row_start = ptr_base;
358	    ptr = ptr_row_start;
359	    sub_len = shift = 0;
360	    /* decoder */
361	    pass = 0;
362	    y = 0;
363	    p_stack = gif->lzw_cache;
364	    p_suffix = gif->lzw_cache + LZW_TABLE_SIZE;
365	    p_prefix = (uint16_t*)(gif->lzw_cache + LZW_TABLE_SIZE * 2);
366	    frm_off = 0;
367	    frm_size = gif->fw * gif->fh;
368	    curr_size = key_size + 1;
369	    top_slot = 1 << curr_size;
370	    new_codes = clear_code + 2;
371	    slot = new_codes;
372	    first_value = -1;
373	    last_key = -1;
374	    sp = p_stack;
375	
376	    while (frm_off < frm_size) {
377	        /* copy data to frame buffer */
378	        while (sp > p_stack) {
379	            *ptr++ = *(--sp);
380	            frm_off += 1;
381	            /* read one line */
382	            if ((ptr - ptr_row_start) == gif->fw) {
383	                if (interlace) {
384	                    switch(pass) {
385	                    case 0:
386	                    case 1:
387	                        y += 8;
388	                        ptr_row_start += linesize * 8;
389	                        break;
390	                    case 2:
391	                        y += 4;
392	                        ptr_row_start += linesize * 4;
393	                        break;
394	                    case 3:
395	                        y += 2;
396	                        ptr_row_start += linesize * 2;
397	                        break;
398	                    default:
399	                        break;
400	                    }
401	                    while (y >= gif->fh) {
402	                        y  = 4 >> pass;
403	                        ptr_row_start = ptr_base + linesize * y;
404	                        pass++;
405	                    }
406	                } else {
407	                    ptr_row_start += linesize;
408	                }
409	                ptr = ptr_row_start;
410	            }
411	        }
412	
413	        key = get_key(gif, curr_size, &sub_len, &shift, &byte);
414	
415	        if (key == stop_code || key >= LZW_TABLE_SIZE)
416	            break;
417	
418	        if (key == clear_code) {
419	            curr_size = key_size + 1;
420	            slot = new_codes;
421	            top_slot = 1 << curr_size;
422	            first_value = last_key = -1;
423	            sp = p_stack;
424	            continue;
425	        }
426	
427	        curr_code = key;
428	        /*
429	         * If the current code is a code that will be added to the decoding
430	         * dictionary, it is composed of the data list corresponding to the
431	         * previous key and its first data.
432	         * */
433	        if (curr_code == slot && first_value >= 0) {
434	            *sp++ = first_value;
435	            curr_code = last_key;
436	        }else if(curr_code >= slot)
437	            break;
438	
439	        while (curr_code >= new_codes) {
440	            *sp++ = p_suffix[curr_code];
441	            curr_code = p_prefix[curr_code];
442	        }
443	        *sp++ = curr_code;
444	
445	        /* Add code to decoding dictionary */
446	        if (slot < top_slot && last_key >= 0) {
447	            p_suffix[slot] = curr_code;
448	            p_prefix[slot++] = last_key;
449	        }
450	        first_value = curr_code;
451	        last_key = key;
452	        if (slot >= top_slot) {
453	            if (curr_size < LZW_MAXBITS) {
454	                top_slot <<= 1;
455	                curr_size += 1;
456	            }
457	        }
458	    }
459	
460	    if (key == stop_code) f_gif_read(gif, &sub_len, 1); /* Must be zero! */
461	    f_gif_seek(gif, end, LV_FS_SEEK_SET);
462	    return ret;
463	}
464	#else
465	static Table *
466	new_table(int key_size)
467	{
468	    int key;
469	    int init_bulk = MAX(1 << (key_size + 1), 0x100);
470	    Table * table = lv_malloc(sizeof(*table) + sizeof(Entry) * init_bulk);
471	    if(table) {
472	        table->bulk = init_bulk;
473	        table->nentries = (1 << key_size) + 2;
474	        table->entries = (Entry *) &table[1];
475	        for(key = 0; key < (1 << key_size); key++)
476	            table->entries[key] = (Entry) {
477	            1, 0xFFF, key
478	        };
479	    }
480	    return table;
481	}
482	
483	/* Add table entry. Return value:
484	 *  0 on success
485	 *  +1 if key size must be incremented after this addition
486	 *  -1 if could not realloc table */
487	static int
488	add_entry(Table ** tablep, uint16_t length, uint16_t prefix, uint8_t suffix)
489	{
490	    Table * table = *tablep;
491	    if(table->nentries == table->bulk) {
492	        table->bulk *= 2;
493	        table = lv_realloc(table, sizeof(*table) + sizeof(Entry) * table->bulk);
494	        if(!table) return -1;
495	        table->entries = (Entry *) &table[1];
496	        *tablep = table;
497	    }
498	    table->entries[table->nentries] = (Entry) {
499	        length, prefix, suffix
500	    };
501	    table->nentries++;
502	    if((table->nentries & (table->nentries - 1)) == 0)
503	        return 1;
504	    return 0;
505	}
