507	/* Compute output index of y-th input line, in frame of height h. */
508	static int
509	interlaced_line_index(int h, int y)
510	{
511	    int p; /* number of lines in current pass */
512	
513	    p = (h - 1) / 8 + 1;
514	    if(y < p)  /* pass 1 */
515	        return y * 8;
516	    y -= p;
517	    p = (h - 5) / 8 + 1;
518	    if(y < p)  /* pass 2 */
519	        return y * 8 + 4;
520	    y -= p;
521	    p = (h - 3) / 4 + 1;
522	    if(y < p)  /* pass 3 */
523	        return y * 4 + 2;
524	    y -= p;
525	    /* pass 4 */
526	    return y * 2 + 1;
527	}
