529	/* Decompress image pixels.
530	 * Return 0 on success or -1 on out-of-memory (w.r.t. LZW code table). */
531	static int
532	read_image_data(gd_GIF * gif, int interlace)
533	{
534	    uint8_t sub_len, shift, byte;
535	    int init_key_size, key_size, table_is_full = 0;
536	    int frm_off, frm_size, str_len = 0, i, p, x, y;
537	    uint16_t key, clear, stop;
538	    int ret;
539	    Table * table;
540	    Entry entry = {0};
541	    size_t start, end;
542	
543	    f_gif_read(gif, &byte, 1);
544	    key_size = (int) byte;
545	    start = f_gif_seek(gif, 0, LV_FS_SEEK_CUR);
546	    discard_sub_blocks(gif);
547	    end = f_gif_seek(gif, 0, LV_FS_SEEK_CUR);
548	    f_gif_seek(gif, start, LV_FS_SEEK_SET);
549	    clear = 1 << key_size;
550	    stop = clear + 1;
551	    table = new_table(key_size);
552	    key_size++;
553	    init_key_size = key_size;
554	    sub_len = shift = 0;
555	    key = get_key(gif, key_size, &sub_len, &shift, &byte); /* clear code */
556	    frm_off = 0;
557	    ret = 0;
558	    frm_size = gif->fw * gif->fh;
559	    while(frm_off < frm_size) {
560	        if(key == clear) {
561	            key_size = init_key_size;
562	            table->nentries = (1 << (key_size - 1)) + 2;
563	            table_is_full = 0;
564	        }
565	        else if(!table_is_full) {
566	            ret = add_entry(&table, str_len + 1, key, entry.suffix);
567	            if(ret == -1) {
568	                lv_free(table);
569	                return -1;
570	            }
571	            if(table->nentries == 0x1000) {
572	                ret = 0;
573	                table_is_full = 1;
574	            }
575	        }
576	        key = get_key(gif, key_size, &sub_len, &shift, &byte);
577	        if(key == clear) continue;
578	        if(key == stop || key == 0x1000) break;
579	        if(ret == 1) key_size++;
580	        entry = table->entries[key];
581	        str_len = entry.length;
582	        for(i = 0; i < str_len; i++) {
583	            p = frm_off + entry.length - 1;
584	            x = p % gif->fw;
585	            y = p / gif->fw;
586	            if(interlace)
587	                y = interlaced_line_index((int) gif->fh, y);
588	            gif->frame[(gif->fy + y) * gif->width + gif->fx + x] = entry.suffix;
589	            if(entry.prefix == 0xFFF)
590	                break;
591	            else
592	                entry = table->entries[entry.prefix];
593	        }
594	        frm_off += str_len;
595	        if(key < table->nentries - 1 && !table_is_full)
596	            table->entries[table->nentries - 1].suffix = entry.suffix;
597	    }
598	    lv_free(table);
599	    if(key == stop) f_gif_read(gif, &sub_len, 1);  /* Must be zero! */
600	    f_gif_seek(gif, end, LV_FS_SEEK_SET);
601	    return 0;
602	}
603	
