606	/* Read image.
607	 * Return 0 on success or -1 on out-of-memory (w.r.t. LZW code table). */
608	static int
609	read_image(gd_GIF * gif)
610	{
611	    uint8_t fisrz;
612	    int interlace;
613	
614	    /* Image Descriptor. */
615	    gif->fx = read_num(gif);
616	    gif->fy = read_num(gif);
617	    gif->fw = read_num(gif);
618	    gif->fh = read_num(gif);
619	    f_gif_read(gif, &fisrz, 1);
620	    interlace = fisrz & 0x40;
621	    /* Ignore Sort Flag. */
622	    /* Local Color Table? */
623	    if(fisrz & 0x80) {
624	        /* Read LCT */
625	        gif->lct.size = 1 << ((fisrz & 0x07) + 1);
626	        f_gif_read(gif, gif->lct.colors, 3 * gif->lct.size);
627	        gif->palette = &gif->lct;
628	    }
629	    else
630	        gif->palette = &gif->gct;
631	    /* Image Data. */
632	    return read_image_data(gif, interlace);
633	}
634	
635	static void
636	render_frame_rect(gd_GIF * gif, uint8_t * buffer)
637	{
638	    int i = gif->fy * gif->width + gif->fx;
639	#ifdef GIFDEC_RENDER_FRAME
640	    GIFDEC_RENDER_FRAME(&buffer[i * 4], gif->fw, gif->fh, gif->width,
641	                        &gif->frame[i], gif->palette->colors,
642	                        gif->gce.transparency ? gif->gce.tindex : 0x100);
643	#else
644	    int j, k;
645	    uint8_t index, * color;
646	
647	    for(j = 0; j < gif->fh; j++) {
648	        for(k = 0; k < gif->fw; k++) {
649	            index = gif->frame[(gif->fy + j) * gif->width + gif->fx + k];
650	            color = &gif->palette->colors[index * 3];
651	            if(!gif->gce.transparency || index != gif->gce.tindex) {
652	                buffer[(i + k) * 4 + 0] = *(color + 2);
653	                buffer[(i + k) * 4 + 1] = *(color + 1);
654	                buffer[(i + k) * 4 + 2] = *(color + 0);
655	                buffer[(i + k) * 4 + 3] = 0xFF;
656	            }
657	        }
658	        i += gif->width;
659	    }
660	#endif
661	}
662	
663	static void
664	dispose(gd_GIF * gif)
665	{
666	    int i;
667	    uint8_t * bgcolor;
668	    switch(gif->gce.disposal) {
669	        case 2: /* Restore to background color. */
670	            bgcolor = &gif->palette->colors[gif->bgindex * 3];
671	
672	            uint8_t opa = 0xff;
673	            if(gif->gce.transparency) opa = 0x00;
674	
675	            i = gif->fy * gif->width + gif->fx;
676	#ifdef GIFDEC_FILL_BG
677	            GIFDEC_FILL_BG(&(gif->canvas[i * 4]), gif->fw, gif->fh, gif->width, bgcolor, opa);
678	#else
679	            int j, k;
680	            for(j = 0; j < gif->fh; j++) {
681	                for(k = 0; k < gif->fw; k++) {
682	                    gif->canvas[(i + k) * 4 + 0] = *(bgcolor + 2);
683	                    gif->canvas[(i + k) * 4 + 1] = *(bgcolor + 1);
684	                    gif->canvas[(i + k) * 4 + 2] = *(bgcolor + 0);
685	                    gif->canvas[(i + k) * 4 + 3] = opa;
686	                }
687	                i += gif->width;
688	            }
689	#endif
690	            break;
691	        case 3: /* Restore to previous, i.e., don't update canvas.*/
692	            break;
693	        default:
694	            /* Add frame non-transparent pixels to canvas. */
695	            render_frame_rect(gif, gif->canvas);
696	    }
697	}
