699	/* Return 1 if got a frame; 0 if got GIF trailer; -1 if error. */
700	int
701	gd_get_frame(gd_GIF * gif)
702	{
703	    char sep;
704	
705	    dispose(gif);
706	    f_gif_read(gif, &sep, 1);
707	    while(sep != ',') {
708	        if(sep == ';') {
709	            f_gif_seek(gif, gif->anim_start, LV_FS_SEEK_SET);
710	            if(gif->loop_count == 1 || gif->loop_count < 0) {
711	                return 0;
712	            }
713	            else if(gif->loop_count > 1) {
714	                gif->loop_count--;
715	            }
716	        }
717	        else if(sep == '!')
718	            read_ext(gif);
719	        else return -1;
720	        f_gif_read(gif, &sep, 1);
721	    }
722	    if(read_image(gif) == -1)
723	        return -1;
724	    return 1;
725	}
