747	static bool f_gif_open(gd_GIF * gif, const void * path, bool is_file)
748	{
749	    gif->f_rw_p = 0;
750	    gif->data = NULL;
751	    gif->is_file = is_file;
752	
753	    if(is_file) {
754	        lv_fs_res_t res = lv_fs_open(&gif->fd, path, LV_FS_MODE_RD);
755	        if(res != LV_FS_RES_OK) return false;
756	        else return true;
757	    }
758	    else {
759	        gif->data = path;
760	        return true;
761	    }
762	}
763	
764	static void f_gif_read(gd_GIF * gif, void * buf, size_t len)
765	{
766	    if(gif->is_file) {
767	        lv_fs_read(&gif->fd, buf, len, NULL);
768	    }
769	    else {
770	        memcpy(buf, &gif->data[gif->f_rw_p], len);
771	        gif->f_rw_p += len;
772	    }
773	}
774	
775	static int f_gif_seek(gd_GIF * gif, size_t pos, int k)
776	{
777	    if(gif->is_file) {
778	        lv_fs_seek(&gif->fd, pos, k);
779	        uint32_t x;
780	        lv_fs_tell(&gif->fd, &x);
781	        return x;
782	    }
783	    else {
784	        if(k == LV_FS_SEEK_CUR) gif->f_rw_p += pos;
785	        else if(k == LV_FS_SEEK_SET) gif->f_rw_p = pos;
786	        return gif->f_rw_p;
787	    }
788	}
789	
790	static void f_gif_close(gd_GIF * gif)
791	{
792	    if(gif->is_file) {
793	        lv_fs_close(&gif->fd);
794	    }
795	}
