132	/**
133	 * @brief 切换到指定索引的表情GIF
134	 */
135	static void switch_to_expression(int index)
136	{
137	  if (s_expr_count <= 0 || s_expr_gif == NULL)
138	    {
139	      return;
140	    }
141	
142	  /* 循环取模，确保索引在有效范围内 */
143	  index = index % s_expr_count;
144	  if (index < 0)
145	    {
146	      index += s_expr_count;
147	    }
148	
149	  s_curr_index = index;
150	
151	  const void *gif_src = watch_resource_get_img_expression(index);
152	  if (gif_src == NULL)
153	    {
154	      PAGE_LOG("ERROR: Failed to get expression data at index %d", index);
155	      return;
156	    }
157	
158	  /* 淡出当前图片 */
159	  lv_obj_set_style_opa(s_expr_gif, LV_OPA_TRANSP, 0);
160	
161	  /* 设置GIF嵌入式数据源 */
162	  lv_gif_set_src(s_expr_gif, gif_src);
163	
164	  /* 重启GIF动画 */
165	  lv_gif_restart(s_expr_gif);
166	
167	  /* 淡入新图片（使用exec_cb回调实际更新透明度） */
168	  lv_anim_t fade_anim;
169	  lv_anim_init(&fade_anim);
170	  lv_anim_set_var(&fade_anim, s_expr_gif);
171	  lv_anim_set_exec_cb(&fade_anim, fade_in_anim_cb);
172	  lv_anim_set_values(&fade_anim, LV_OPA_TRANSP, LV_OPA_COVER);
173	  lv_anim_set_time(&fade_anim, WATCH_EXPRESSION_FADE_TIME_MS);
174	  lv_anim_set_path_cb(&fade_anim, lv_anim_path_ease_out);
175	  lv_anim_start(&fade_anim);
176	}
