182	lv_obj_t *watch_expression_page_init(lv_obj_t *parent)
183	{
184	  if (s_page_root != NULL)
185	    {
186	      return s_page_root;
187	    }
188	
189	  /* 获取表情图片总数 */
190	  s_expr_count = watch_resource_get_expression_count();
191	  if (s_expr_count <= 0)
192	    {
193	      PAGE_LOG("ERROR: No expression images registered");
194	      return NULL;
195	    }
196	
197	  /* 创建页面根容器 */
198	  s_page_root = lv_obj_create(parent);
199	  lv_obj_set_size(s_page_root, WATCH_SCREEN_WIDTH, WATCH_SCREEN_HEIGHT);
200	  lv_obj_set_style_bg_color(s_page_root, lv_color_hex(0x000000), 0);
201	  lv_obj_set_style_border_width(s_page_root, 0, 0);
202	  lv_obj_set_style_radius(s_page_root, 0, 0);
203	  lv_obj_set_style_pad_all(s_page_root, 0, 0);
204	  lv_obj_clear_flag(s_page_root, LV_OBJ_FLAG_SCROLLABLE);
205	  lv_obj_center(s_page_root);
206	
207	  /* 创建GIF控件 */
208	  s_expr_gif = lv_gif_create(s_page_root);
209	  lv_obj_center(s_expr_gif);
210	
211	  /* 设置GIF控件背景透明。
212	   * 首次加载时不做淡入动画——直接显示第一帧，
213	   * 避免从开机动画切换到表情页时出现黑屏间隙。
214	   * 后续轮播切换由 switch_to_expression() 走淡入/淡出流程。 */
215	  lv_obj_set_style_bg_opa(s_expr_gif, LV_OPA_TRANSP, 0);
216	  lv_obj_set_style_opa(s_expr_gif, LV_OPA_COVER, 0);
217	
218	  /* 让LVGL处理一次事件循环，确保控件完全初始化 */
219	  lv_timer_handler();
220	
221	  /* 加载第一张表情GIF，如果失败则依次尝试后续表情 */
222	  int i;
223	  for (i = 0; i < s_expr_count; i++)
224	    {
225	      s_curr_index = i;
226	      const void *first_gif = watch_resource_get_img_expression(s_curr_index);
227	      if (first_gif == NULL)
228	        continue;
229	
230	      lv_gif_set_src(s_expr_gif, first_gif);
231	
232	      int32_t w = lv_obj_get_width(s_expr_gif);
233	      int32_t h = lv_obj_get_height(s_expr_gif);
234	
235	      if (w > 0 && h > 0)
236	        {
237	          /* 首张GIF加载成功，重启播放 */
238	          lv_gif_restart(s_expr_gif);
239	          break;
240	        }
241	    }
242	
243	  return s_page_root;
244	}
