88	        }
89	    }
90	
91	    /*Run all timer from the list*/
92	    lv_timer_t * next;
93	    lv_timer_t * timer_active;
94	    lv_ll_t * timer_head = timer_ll_p;
95	    do {
96	        state_p->timer_deleted             = false;
97	        state_p->timer_created             = false;
98	
99	        timer_active = _lv_ll_get_head(timer_head);
100	        while(timer_active) {
101	            /*The timer might be deleted if it runs only once ('repeat_count = 1')
102	             *So get next element until the current is surely valid*/
103	            next = _lv_ll_get_next(timer_head, timer_active);
104	
105	            if(lv_timer_exec(timer_active)) {
106	                /*If a timer was created or deleted then this or the next item might be corrupted*/
107	                if(state_p->timer_created || state_p->timer_deleted) {
108	                    LV_TRACE_TIMER("Start from the first timer again because a timer was created or deleted");
109	                    break;
110	                }
111	            }
112	
113	            timer_active = next; /*Load the next timer*/
114	        }
115	    } while(timer_active);
116	
117	    uint32_t time_until_next = LV_NO_TIMER_READY;
118	    next = _lv_ll_get_head(timer_head);
119	    while(next) {
120	        if(!next->paused) {
121	            uint32_t delay = lv_timer_time_remaining(next);
122	            if(delay < time_until_next)
123	                time_until_next = delay;
124	        }
125	
126	        next = _lv_ll_get_next(timer_head, next); /*Find the next timer*/
127	    }
128	
129	    state_p->busy_time += lv_tick_elaps(handler_start);
130	    uint32_t idle_period_time = lv_tick_elaps(state_p->idle_period_start);
131	    if(idle_period_time >= IDLE_MEAS_PERIOD) {
132	        state_p->idle_last         = (state_p->busy_time * 100) / idle_period_time;  /*Calculate the busy percentage*/
133	        state_p->idle_last         = state_p->idle_last > 100 ? 0 : 100 - state_p->idle_last; /*But we need idle time*/
134	        state_p->busy_time         = 0;
135	        state_p->idle_period_start = lv_tick_get();
136	    }
137	
138	    state_p->timer_time_until_next = time_until_next;
139	    state_p->already_running = false; /*Release the mutex*/
